package com.telibot.bridge;
import android.app.*;import android.os.Bundle;import android.content.pm.PackageManager;import android.widget.*;import android.text.InputType;import android.view.WindowManager;import java.net.URL;import java.util.*;
public final class MainActivity extends Activity {
 final Map<String,EditText> fields=new LinkedHashMap<>();Switch enabled;LinearLayout box;TextView status;
 EditText field(String key,String label,boolean secret){TextView l=new TextView(this);l.setText(label);box.addView(l);EditText e=new EditText(this);e.setSingleLine(true);e.setTextSize(14);e.setInputType(secret?129:InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);e.setSaveEnabled(false);e.setImportantForAutofill(2);if(!secret)e.setText(Store.prefs(this).getString(key,key.equals("url")?"https://digital-product-telibot.pages.dev/api/mobile-receipt":""));box.addView(e);fields.put(key,e);return e;}
 String value(String k){return fields.get(k).getText().toString().trim();}
 void say(String t){status.setText(t);}
 public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);ScrollView scroll=new ScrollView(this);box=new LinearLayout(this);box.setOrientation(1);int pad=(int)(20*getResources().getDisplayMetrics().density);box.setPadding(pad,pad,pad,pad);scroll.addView(box);setContentView(scroll);
 TextView title=new TextView(this);title.setText("TeliBot Receipt Bridge · 0.1");title.setTextSize(22);box.addView(title);
 TextView intro=new TextView(this);intro.setText("শুধু নতুন পেমেন্ট SMS → আপনার সার্ভার। পুরোনো ইনবক্স পড়বে না। OTP/অন্য SMS পাঠাবে না।\n\nবিকাশ ও নগদের প্রদত্ত SMS format সমর্থিত। রকেটের নমুনা বাকি। এটি সরাসরি provider verification নয়।");box.addView(intro);
 android.content.SharedPreferences p=Store.prefs(this);if(!p.contains("device"))p.edit().putString("device",UUID.randomUUID().toString()).apply();TextView device=new TextView(this);device.setText("Device ID: "+p.getString("device",""));device.setTextIsSelectable(true);box.addView(device);
 field("url","আপনার receipt endpoint (HTTPS)",false);field("secret","Signing Key (কমপক্ষে ৩২ অক্ষর; ফাঁকা রাখলে আগেরটি থাকবে)",true);
 for(String method:new String[]{"bkash","nagad"}){TextView h=new TextView(this);h.setText("\n"+method.toUpperCase(Locale.ROOT));h.setTextSize(19);box.addView(h);field(method+"Sender","কোম্পানির হুবহু SMS sender (মোবাইল নম্বর নয়)",false);field(method+"Account","টাকা পাওয়ার account number",false);}
 enabled=new Switch(this);enabled.setText("পেমেন্ট SMS forwarding চালু");enabled.setChecked(p.getBoolean("enabled",false));box.addView(enabled);
 Button save=new Button(this);save.setText("Save settings");box.addView(save);save.setOnClickListener(v->save());
 Button permission=new Button(this);permission.setText("নতুন SMS গ্রহণের permission দিন");box.addView(permission);permission.setOnClickListener(v->requestPermissions(new String[]{"android.permission.RECEIVE_SMS"},1));
 Button test=new Button(this);test.setText("SMS format ফোনেই পরীক্ষা করুন");box.addView(test);test.setOnClickListener(v->preview());
 Button retry=new Button(this);retry.setText("Pending receipts আবার পাঠান");box.addView(retry);retry.setOnClickListener(v->{UploadJob.schedule(this);say("চেষ্টা করা হবে। রেকর্ড গ্রহণ করা মানেই ব্যালেন্স যোগ নয়।");});
 Button stop=new Button(this);stop.setText("বন্ধ করুন ও pending receipts মুছুন");box.addView(stop);stop.setOnClickListener(v->{p.edit().putBoolean("enabled",false).apply();enabled.setChecked(false);((android.app.job.JobScheduler)getSystemService(JOB_SCHEDULER_SERVICE)).cancel(43);try(Store s=new Store(this)){s.getWritableDatabase().delete("receipts",null,null);}say("Forwarding বন্ধ। Pending receipts মুছে গেছে।");});
 status=new TextView(this);box.addView(status);say("Forwarding: "+(p.getBoolean("enabled",false)?"ON":"OFF")+"\nবাস্তব ফোনে পরীক্ষা বাকি থাকলে OFF রাখুন।");
 }
 void save(){try{String endpoint=value("url"),secret=value("secret");if(!endpoint.isEmpty()){URL u=new URL(endpoint);if(!u.getProtocol().equals("https")||u.getHost().isEmpty()||u.getUserInfo()!=null||u.getQuery()!=null||u.getRef()!=null)throw new Exception("শুধু সরাসরি HTTPS endpoint দিন।");}
  android.content.SharedPreferences p=Store.prefs(this);if(!secret.isEmpty()&&(secret.length()<32||secret.length()>256))throw new Exception("Signing Key ৩২–২৫৬ অক্ষর হতে হবে।");boolean configured=false;
  for(String m:new String[]{"bkash","nagad"}){String sender=value(m+"Sender"),account=value(m+"Account");if(sender.isEmpty()&&account.isEmpty())continue;
   if(!sender.matches("[A-Za-z][A-Za-z0-9 -]{1,24}|[0-9]{3,6}"))throw new Exception("কোম্পানির sender দিন; সাধারণ মোবাইল নম্বর গ্রহণ হবে না।");if(!account.matches(m.equals("rocket")?"01[3-9][0-9]{8,9}":"01[3-9][0-9]{8}"))throw new Exception("সঠিক receiving account দিন।");configured=true;
  }
  if(enabled.isChecked()&&(!configured||endpoint.isEmpty()||(secret.isEmpty()&&!p.contains("secret"))||checkSelfPermission("android.permission.RECEIVE_SMS")!=PackageManager.PERMISSION_GRANTED))throw new Exception("চালুর আগে SMS permission, method account, HTTPS URL ও Signing Key দিন।");
  // Disable and clear old pending data when changing configuration to prevent rerouting receipts.
  p.edit().putBoolean("enabled",false).commit();((android.app.job.JobScheduler)getSystemService(JOB_SCHEDULER_SERVICE)).cancel(43);try(Store s=new Store(this)){s.getWritableDatabase().delete("receipts",null,null);}android.content.SharedPreferences.Editor e=p.edit();for(String k:fields.keySet())if(!k.equals("secret"))e.putString(k,value(k));if(!secret.isEmpty())e.putString("secret",Store.seal(secret));e.putBoolean("enabled",enabled.isChecked()).commit();fields.get("secret").setText("");say("Saved. Forwarding "+(enabled.isChecked()?"ON":"OFF")+"। বাস্তব SMS দিয়ে end-to-end পরীক্ষা প্রয়োজন।");
 }catch(Exception ex){say("সেভ হয়নি: "+ex.getMessage());}}
 void preview(){EditText input=new EditText(this);input.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE|InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);input.setSaveEnabled(false);input.setImportantForAutofill(2);new AlertDialog.Builder(this).setTitle("SMS নমুনা · শুধু ফোনে পরীক্ষা").setView(input).setPositiveButton("পরীক্ষা",(d,w)->{String result="সমর্থিত SMS format মেলেনি / নিরাপত্তার জন্য বাদ।";for(String m:new String[]{"bkash","nagad"}){ReceiptParser.Receipt r=ReceiptParser.parse(input.getText().toString(),m);if(r!=null){result=m+" · BDT "+java.math.BigDecimal.valueOf(r.minor,2).toPlainString()+" · TrxID "+r.trx+"\nএটি পরীক্ষামাত্র; সার্ভারে পাঠানো হয়নি।";break;}}input.setText("");say(result);}).setNegativeButton("বাতিল",(d,w)->input.setText("")).show();}
}
